mapper.select:
SELECT idDieta, nombreDieta, caloriasTotales, descripcion, estatusEdicion
FROM dieta
WHERE idDieta = #{idDieta}

mapper.update:
UPDATE dieta
SET nombreDieta = #{nombreDieta},
    caloriasTotales = #{caloriasTotales},
    descripcion = #{descripcion},
    estatusEdicion = #{estatusEdicion}
WHERE idDieta = #{idDieta}
